using System.Net;
using System.Net.Http.Headers;
using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.DependencyInjection;
using PowerXPlugin.Framework.Runtime.Capability;
using PowerXPlugin.Framework.Runtime.Common;

namespace PowerXPlugin.Framework.Runtime.Customer;

public sealed record CustomerCredential(string Type, string Value);
public sealed record CustomerAuthRequest(string Channel, CustomerCredential Credential);
public sealed record CustomerContext([property: JsonPropertyName("tenant_uuid")] string TenantUuid, [property: JsonPropertyName("customer_uuid")] string CustomerUuid, [property: JsonPropertyName("membership_uuid")] string MembershipUuid, IReadOnlyList<string> Roles, IReadOnlyList<string> Scopes, bool Authenticated);
public sealed record CustomerAuthResult([property: JsonPropertyName("access_token")] string AccessToken, [property: JsonPropertyName("refresh_token")] string? RefreshToken, [property: JsonPropertyName("expires_in")] long ExpiresIn, CustomerContext Context);
public sealed record CustomerSession(string TenantUuid, string CustomerUuid, string CustomerBearer);
public sealed record CustomerMembership([property: JsonPropertyName("tenant_uuid")] string TenantUuid, [property: JsonPropertyName("customer_uuid")] string CustomerUuid, [property: JsonPropertyName("membership_uuid")] string MembershipUuid, string Status, IReadOnlyList<string> Roles, IReadOnlyList<string> Scopes, [property: JsonPropertyName("expires_at")] DateTimeOffset? ExpiresAt);
public sealed record ExternalIdentityRequest(string ProviderSubject, string DisplayName, string TraceId = "");
public sealed record ExternalIdentityResolution(string CustomerUuid, string MembershipUuid, string DisplayName);
public interface ICustomerAuthService { Task<CustomerAuthResult> RegisterAsync(CustomerAuthRequest request, CancellationToken ct = default); Task<CustomerAuthResult> LoginAsync(CustomerAuthRequest request, CancellationToken ct = default); Task<CustomerContext> ValidateAsync(CustomerSession session, CancellationToken ct = default); }
public interface ICustomerMembershipService { Task<CustomerMembership> ResolveAsync(CustomerSession session, CancellationToken ct = default); Task<IReadOnlyList<CustomerMembership>> ListAsync(CustomerSession session, CancellationToken ct = default); }
public interface IExternalIdentityService { Task<ExternalIdentityResolution> ResolveAsync(ExternalIdentityRequest request, CancellationToken ct = default); }
public interface ILocalCustomerStore : ICustomerAuthService, ICustomerMembershipService, IExternalIdentityService { }
public static class CustomerValidation { public static void Session(CustomerSession s) { if (!Guid.TryParse(s.TenantUuid, out var t) || t == Guid.Empty || t.ToString()!=s.TenantUuid || !Guid.TryParse(s.CustomerUuid,out var c)||c==Guid.Empty||c.ToString()!=s.CustomerUuid||string.IsNullOrWhiteSpace(s.CustomerBearer)) throw new CustomerException(CustomerErrors.InvalidArgument); } public static void Auth(CustomerAuthRequest r) { if (r is null||r.Channel!="shopify_storefront"||r.Credential?.Type!="shopify_customer_access_token"||string.IsNullOrWhiteSpace(r.Credential.Value)) throw new CustomerException(CustomerErrors.InvalidCredential); } }
public sealed class LocalCustomerRuntime(ILocalCustomerStore store) : ICustomerAuthService, ICustomerMembershipService, IExternalIdentityService { private readonly ILocalCustomerStore _store=store??throw new ArgumentNullException(nameof(store)); public Task<CustomerAuthResult> RegisterAsync(CustomerAuthRequest r,CancellationToken ct=default){CustomerValidation.Auth(r);return _store.RegisterAsync(r,ct);} public Task<CustomerAuthResult> LoginAsync(CustomerAuthRequest r,CancellationToken ct=default){CustomerValidation.Auth(r);return _store.LoginAsync(r,ct);} public Task<CustomerContext> ValidateAsync(CustomerSession s,CancellationToken ct=default){CustomerValidation.Session(s);return _store.ValidateAsync(s,ct);} public Task<CustomerMembership> ResolveAsync(CustomerSession s,CancellationToken ct=default){CustomerValidation.Session(s);return _store.ResolveAsync(s,ct);} public Task<IReadOnlyList<CustomerMembership>> ListAsync(CustomerSession s,CancellationToken ct=default){CustomerValidation.Session(s);return _store.ListAsync(s,ct);} public Task<ExternalIdentityResolution> ResolveAsync(ExternalIdentityRequest r,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(r.ProviderSubject)||string.IsNullOrWhiteSpace(r.DisplayName))throw new CustomerException(CustomerErrors.InvalidArgument);return _store.ResolveAsync(r,ct);} }
public sealed class PowerXCustomerClient(string baseUrl,string tenantUuid,IServiceCredentialProvider credentials,HttpClient? http=null):ICustomerAuthService,ICustomerMembershipService { private readonly string _base=baseUrl.TrimEnd('/'); private readonly string _tenant=tenantUuid; private readonly IServiceCredentialProvider _credentials=credentials; private readonly HttpClient _http=http??new(); public Task<CustomerAuthResult> RegisterAsync(CustomerAuthRequest r,CancellationToken ct=default)=>Auth("/api/v1/tenant/customer/auth/register",r,ct); public Task<CustomerAuthResult> LoginAsync(CustomerAuthRequest r,CancellationToken ct=default)=>Auth("/api/v1/tenant/customer/auth/login",r,ct); public async Task<CustomerContext> ValidateAsync(CustomerSession s,CancellationToken ct=default){var x=await Send<CustomerContext>(s,HttpMethod.Post,"/api/v1/tenant/customer/auth/validate",null,ct);return Check(x,s);} public async Task<CustomerMembership> ResolveAsync(CustomerSession s,CancellationToken ct=default)=>Check(await Send<CustomerMembership>(s,HttpMethod.Post,"/api/v1/tenant/customer/memberships:resolve",null,ct),s); public async Task<IReadOnlyList<CustomerMembership>> ListAsync(CustomerSession s,CancellationToken ct=default)=>[Check(await Send<CustomerMembership>(s,HttpMethod.Get,"/api/v1/tenant/customer/memberships",null,ct),s)]; private async Task<CustomerAuthResult> Auth(string path,CustomerAuthRequest r,CancellationToken ct){CustomerValidation.Auth(r);var c=(await _credentials.GetCredentialAsync(ct)).Validate();using var m=new HttpRequestMessage(HttpMethod.Post,_base+path){Content=new StringContent(JsonSerializer.Serialize(new{channel=r.Channel,credential=r.Credential}),Encoding.UTF8,"application/json")};m.Headers.Authorization=new AuthenticationHeaderValue(c.NormalizedAuthScheme,c.Value);return await Decode<CustomerAuthResult>(m,ct);} private async Task<T> Send<T>(CustomerSession s,HttpMethod method,string path,object? body,CancellationToken ct){CustomerValidation.Session(s);if(s.TenantUuid!=_tenant)throw new CustomerException(CustomerErrors.TenantMismatch);var c=(await _credentials.GetCredentialAsync(ct)).Validate();using var m=new HttpRequestMessage(method,_base+path);m.Headers.Authorization=new AuthenticationHeaderValue(c.NormalizedAuthScheme,c.Value);m.Headers.TryAddWithoutValidation("X-PowerX-Customer-Authorization","Bearer "+s.CustomerBearer);if(body is not null)m.Content=new StringContent(JsonSerializer.Serialize(body),Encoding.UTF8,"application/json");return await Decode<T>(m,ct);} private async Task<T> Decode<T>(HttpRequestMessage m,CancellationToken ct){using var r=await _http.SendAsync(m,ct);var raw=await r.Content.ReadAsStringAsync(ct);if(!r.IsSuccessStatusCode)throw new CustomerException(r.StatusCode==HttpStatusCode.Forbidden?CustomerErrors.Forbidden:r.StatusCode==HttpStatusCode.Unauthorized?CustomerErrors.Unauthorized:CustomerErrors.Upstream);using var j=JsonDocument.Parse(raw);if(!j.RootElement.TryGetProperty("data",out var d))throw new CustomerException(CustomerErrors.InvalidResponse);return JsonSerializer.Deserialize<T>(d.GetRawText(),new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new CustomerException(CustomerErrors.InvalidResponse);} private static CustomerContext Check(CustomerContext x,CustomerSession s){if(x.TenantUuid!=s.TenantUuid||x.CustomerUuid!=s.CustomerUuid||!x.Authenticated)throw new CustomerException(CustomerErrors.TenantMismatch);return x;} private static CustomerMembership Check(CustomerMembership x,CustomerSession s){if(x.TenantUuid!=s.TenantUuid||x.CustomerUuid!=s.CustomerUuid||x.Status!="active")throw new CustomerException(CustomerErrors.TenantMismatch);return x;} }
public sealed class DelegatedExternalIdentityService(ICapabilityRegistry capabilities):IExternalIdentityService { public async Task<ExternalIdentityResolution> ResolveAsync(ExternalIdentityRequest r,CancellationToken ct=default){if(string.IsNullOrWhiteSpace(r.ProviderSubject)||string.IsNullOrWhiteSpace(r.DisplayName))throw new CustomerException(CustomerErrors.InvalidArgument);var o=await capabilities.InvokeAsync(new("com.corex.customer.external_identities.resolve",null,null,"core_internal",null,r.TraceId,null,new Dictionary<string,object?>{{"method","INVOKE"},{"endpoint","core://customer/external-identities/resolve"},{"body",new{provider_subject=r.ProviderSubject,display_name=r.DisplayName}}},null),ct);var p=o.Payload??throw new CustomerException(CustomerErrors.InvalidResponse);var raw=JsonSerializer.Serialize(p);using var j=JsonDocument.Parse(raw);var item=j.RootElement.GetProperty("item");return new(item.GetProperty("customer_uuid").GetString()??"",item.GetProperty("membership_uuid").GetString()??"",item.GetProperty("display_name").GetString()??"");} }
public static class CustomerRuntimeExtensions { public static IServiceCollection AddPowerXCustomerRuntime(this IServiceCollection s,ProviderMode m,Func<IServiceProvider,ICustomerAuthService> a,Func<IServiceProvider,ICustomerMembershipService> ms,Func<IServiceProvider,IExternalIdentityService> e,Func<IServiceProvider,ICustomerAuthService> da,Func<IServiceProvider,ICustomerMembershipService> dm,Func<IServiceProvider,IExternalIdentityService> de){s.AddPowerXRuntime("customer.auth",m,a,da);s.AddPowerXRuntime("customer.membership",m,ms,dm);return s.AddPowerXRuntime("customer.external-identity",m,e,de);} }
public static class CustomerErrors { public const string InvalidArgument="FRAMEWORK_CUSTOMER_INVALID_ARGUMENT",InvalidCredential="FRAMEWORK_CUSTOMER_INVALID_CREDENTIAL",InvalidResponse="FRAMEWORK_CUSTOMER_INVALID_RESPONSE",TenantMismatch="FRAMEWORK_CUSTOMER_TENANT_MISMATCH",Unauthorized="FRAMEWORK_CUSTOMER_UNAUTHORIZED",Forbidden="FRAMEWORK_CUSTOMER_FORBIDDEN",Upstream="FRAMEWORK_CUSTOMER_UPSTREAM_DEPENDENCY"; } public sealed class CustomerException(string code):InvalidOperationException(code){public string Code{get;}=code;}
